import { useEffect, useMemo, useRef, useState } from 'react';
import type { Imu, MotionManifest, Prediction, Range } from './data';
import { duration, fmtTime, parseMotion, parsePrediction } from './data';
import { demoMotion, demoPrediction } from './demo';
import { reconstructOrientation, type QuaternionPoint } from './orientation';
import Timeline from './Timeline';
import MotionReplay from './MotionReplay';

type Page = 'Monitor' | 'Events' | 'Model';
type MotionData = { manifest: MotionManifest; imu: Imu };
type Release = { run_key: string; f1: number; outer_metrics?: { f1: number; ppv: number; sensitivity: number; n_tp: number; n_true: number; n_pred: number } };
const mean = (values: number[]) => values.length ? values.reduce((a,b)=>a+b,0)/values.length : null;

function RawChart({ imu, selection, playhead, orientation }: { imu?: Imu; selection: Range | null; playhead: number | null; orientation: QuaternionPoint[] | null }) {
  const [tab,setTab]=useState<'ACC'|'GYRO'|'Orientation'>('ACC');
  const plot=useMemo(()=>{
    if(!imu||!selection)return null;
    const times=tab==='Orientation'&&orientation?orientation.map(p=>p.t):imu.t;
    const series=tab==='Orientation'&&orientation?[orientation.map(p=>p.x),orientation.map(p=>p.y),orientation.map(p=>p.z),orientation.map(p=>p.w)]:tab==='ACC'?[imu.ax,imu.ay,imu.az]:[imu.gx,imu.gy,imu.gz];
    let first=0;while(first<times.length&&times[first]<selection.start_ms)first++;
    let end=first;while(end<times.length&&times[end]<=selection.end_ms)end++;
    if(end<=first)return null;
    let max=tab==='Orientation'?1:.1;
    if(tab!=='Orientation')for(let i=first;i<end;i++)for(const channel of series)max=Math.max(max,Math.abs(channel[i]));
    const step=Math.max(1,Math.floor((end-first)/1000));
    const paths=series.map(channel=>{let path='';for(let i=first;i<end;i+=step){const x=35+(times[i]-selection.start_ms)/Math.max(1,selection.end_ms-selection.start_ms)*557;const y=82.5-channel[i]/max*55;let gap=false;for(let j=Math.max(first+1,i-step+1);j<=i;j++)if(times[j]-times[j-1]>500){gap=true;break;}path+=`${!path||gap?'M':'L'}${x.toFixed(2)} ${y.toFixed(2)} `;}return path;});
    return {paths,max};
  },[imu,selection,tab,orientation]);
  const colors=['#d56f6a','#459775','#5d82d9','#9a79c9'];
  return <section className="panel raw-panel"><div className="panel-title"><h2>{tab==='Orientation'?'Orientation':'Raw IMU'} <span>(selected interval)</span></h2><div className="axis-legend"><span className="axis-x">●</span>{tab==='Orientation'?'qx':'X'} <span className="axis-y">●</span>{tab==='Orientation'?'qy':'Y'} <span className="axis-z">●</span>{tab==='Orientation'?'qz':'Z'}{tab==='Orientation'&&<> <span style={{color:'#9a79c9'}}>●</span>qw</>}</div></div><div className="segmented raw-tabs">{(['ACC','GYRO','Orientation'] as const).map(x=><button key={x} className={tab===x?'active':''} disabled={x==='Orientation'&&!orientation} onClick={()=>setTab(x)}>{x}</button>)}</div>
    {selection&&imu?<div className="raw-chart-wrap"><svg viewBox="0 0 600 165" preserveAspectRatio="none" role="img" aria-label={`${tab} channels for selected interval`}>{[28,64,101,137].map(y=><line key={y} x1="35" y1={y} x2="592" y2={y} stroke="#e7e8e9" strokeWidth="1"/>)}{plot?.paths.map((path,i)=><path key={i} d={path} fill="none" stroke={colors[i]} strokeWidth="1.25" vectorEffect="non-scaling-stroke"/>)}<text x="2" y="29" fill="#7a7e88" fontSize="11">{plot?.max.toFixed(1)||'—'}</text><text x="18" y="86" fill="#7a7e88" fontSize="11">0</text><text x="2" y="141" fill="#7a7e88" fontSize="11">{plot?(-plot.max).toFixed(1):'—'}</text>{playhead!==null&&<line x1={35+(playhead-selection.start_ms)/Math.max(1,selection.end_ms-selection.start_ms)*557} x2={35+(playhead-selection.start_ms)/Math.max(1,selection.end_ms-selection.start_ms)*557} y1="8" y2="151" stroke="#303d4d" strokeWidth="1" vectorEffect="non-scaling-stroke"/>}</svg></div>:<div className="panel-empty">Load motion telemetry and select an interval to inspect raw channels.</div>}
    <p className="unit-note">{tab==='Orientation'?'Quaternion · derived from calibrated IMU':tab==='GYRO'?'GYRO':'ACC'} · Data gaps are not interpolated</p>
  </section>;
}
export default function App(){
  const [page,setPage]=useState<Page>('Monitor'),[prediction,setPrediction]=useState<Prediction>(demoPrediction),[motion,setMotion]=useState<MotionData|null>(demoMotion),[demo,setDemo]=useState(true),[sessionId,setSessionId]=useState(demoPrediction.timeline!.session_ids[0]);
  const [selection,setSelection]=useState<Range|null>({start_ms:demoPrediction.events[0].start_ms+60_000,end_ms:demoPrediction.events[0].start_ms+72_400});
  const [playhead,setPlayhead]=useState<number|null>(selection?.start_ms??null),[playing,setPlaying]=useState(false),[speed,setSpeed]=useState(1),[error,setError]=useState('');
  const [release,setRelease]=useState<Release|null>(null);const fileInput=useRef<HTMLInputElement>(null);
  useEffect(()=>{fetch('./release-metadata.json').then(r=>r.ok?r.json():null).then(setRelease).catch(()=>{});},[]);
  const activeMotion=motion?.manifest.session_id===sessionId?motion:null;
  const orientation=useMemo(()=>activeMotion?reconstructOrientation(activeMotion.imu,activeMotion.manifest):null,[activeMotion]);
  function select(r:Range|null){setSelection(r);setPlaying(false);setPlayhead(r?.start_ms??null);}
  useEffect(()=>{if(!playing||!selection||!orientation)return;let frame=0,last=0;const tick=(now:number)=>{if(last){const next=(playheadRef.current??selection.start_ms)+(now-last)*speed;if(next>=selection.end_ms){setPlayhead(selection.end_ms);setPlaying(false);return;}setPlayhead(next);}last=now;frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);return()=>cancelAnimationFrame(frame);},[playing,selection,speed,orientation]);
  const playheadRef=useRef<number|null>(playhead);playheadRef.current=playhead;
  const events=prediction.events.filter(e=>e.session_id===sessionId),candidates=(prediction.candidates||[]).filter(c=>c.session_id===sessionId);
  const selectedEvent=selection?events.find(e=>e.start_ms<selection.end_ms&&e.end_ms>selection.start_ms):undefined;
  const selectedCandidate=selection?candidates.find(c=>c.start_ms<selection.end_ms&&c.end_ms>selection.start_ms):undefined;
  const selectedImu=useMemo(()=>{if(!selection||!activeMotion)return null;const a=activeMotion.imu,acc:number[]=[],gyro:number[]=[];for(let i=0;i<a.t.length;i++){if(a.t[i]<selection.start_ms)continue;if(a.t[i]>selection.end_ms)break;acc.push(Math.hypot(a.ax[i],a.ay[i],a.az[i]));gyro.push(Math.hypot(a.gx[i],a.gy[i],a.gz[i]));}return{acc:mean(acc),gyro:mean(gyro)};},[selection,activeMotion]);
  const eventTotal=events.reduce((sum,e)=>sum+e.duration_s,0);
  async function load(files:FileList|null){if(!files?.length)return;setError('');try{let p:Prediction|null=null,m:MotionManifest|null=null,b:File|null=null;for(const file of Array.from(files)){if(file.name.endsWith('.bin')){b=file;continue;}if(!file.name.endsWith('.json'))continue;const json=JSON.parse(await file.text());if(json.schema_version)p=parsePrediction(json);else if(json.telemetry_version)m=json as MotionManifest;}
      if(!p&&!m)throw new Error('Choose a prediction JSON or motion telemetry files.');
      if(p){setPrediction(p);setDemo(false);setSessionId(p.timeline?.session_ids?.[0]||p.events[0]?.session_id||'');select(null);setMotion(null);setPage('Monitor');}
      if(m){if(!b)throw new Error('motion.json requires its matching motion.bin in the same selection.');const parsed=parseMotion(m,await b.arrayBuffer());setMotion(parsed);if(!p&&prediction.timeline?.session_ids.includes(m.session_id))setSessionId(m.session_id);else if(p&&!(p.timeline?.session_ids.includes(m.session_id)||p.events.some(e=>e.session_id===m.session_id)))throw new Error('Motion session ID does not match prediction.');}
    }catch(e){setError(e instanceof Error?e.message:String(e));}finally{if(fileInput.current)fileInput.current.value='';}}
  function resetDemo(){setPrediction(demoPrediction);setMotion(demoMotion);setDemo(true);setSessionId(demoPrediction.timeline!.session_ids[0]);select({start_ms:demoPrediction.events[0].start_ms+60_000,end_ms:demoPrediction.events[0].start_ms+72_400});setPage('Monitor');setError('');}
  return <div className="app"><header className="top-nav"><div className="brand"><strong>EatingSense</strong><small>Wrist IMU Eating Event Detection</small></div><nav>{(['Monitor','Events','Model'] as const).map(x=><button key={x} className={page===x?'active':''} onClick={()=>setPage(x)}>{x}</button>)}</nav><div className="top-meta"><span className="offline-dot"/>{demo?'DEMO DATA':'Offline analysis'}<span className="nav-time">{new Date().toLocaleDateString('en-CA')} &nbsp; {new Date().toLocaleTimeString('en-GB',{hour12:false})}</span></div></header>
    <main className={page==="Monitor"?`monitor-workspace${error?" has-error":""}`:undefined}>{error&&<div role="alert" className="error-banner">{error}<button onClick={()=>setError('')}>Dismiss</button></div>}
      <div className="data-bar"><span>{demo?'Session workspace · demo data':prediction.input.source.split(/[\\/]/).pop()}</span><div><input ref={fileInput} type="file" multiple accept=".json,.bin" hidden onChange={e=>load(e.target.files)}/><button onClick={()=>fileInput.current?.click()}>Load data</button><button onClick={resetDemo}>Reset demo</button></div></div>
      {page==='Monitor'&&<><section className="panel status-header"><div><strong>{demo?'Demo monitoring':'Session review'}</strong><span>{sessionId||'No session'}</span></div><div className="status-main"><span className="status-indicator"/><div><strong>{selectedEvent?'Eating event':'No eating event selected'}</strong><span>{selectedEvent?`${fmtTime(selectedEvent.start_ms,true)} – ${fmtTime(selectedEvent.end_ms,true)}`:'Choose an interval on the timeline'}</span></div>{selectedEvent&&<b className="mono">{duration(selectedEvent.end_ms-selectedEvent.start_ms)}</b>}</div><div className="status-metric"><small>IMU</small><strong>{activeMotion?.imu.t.length ? `${Math.round(activeMotion.imu.t.length/Math.max(1,(activeMotion.imu.t[activeMotion.imu.t.length-1]-activeMotion.imu.t[0])/1000))} Hz`:'—'}</strong></div><div className="status-metric"><small>Coverage</small><strong>{(prediction.diagnostics.coverage*100).toFixed(1)}%</strong></div><div className="status-metric"><small>Events in session</small><strong>{events.length}</strong></div><div className="status-metric"><small>Total duration</small><strong>{duration(eventTotal*1000)}</strong></div></section>
        <div className="monitor-grid"><Timeline prediction={prediction} sessionId={sessionId} imu={activeMotion?.imu} selection={selection} onSelect={select} playhead={playhead}/><MotionReplay orientation={orientation} selection={selection} playhead={playhead} playing={playing} speed={speed} onPlay={()=>{if(!selection||!orientation)return;if(playhead===selection.end_ms)setPlayhead(selection.start_ms);setPlaying(!playing);}} onSeek={t=>{setPlaying(false);setPlayhead(t);}} onSpeed={setSpeed}/></div>
        <div className="detail-grid"><section className="panel inspector"><h2>Selected interval</h2>{selection&&selection.end_ms>selection.start_ms?<><div className="interval-time mono">◷ &nbsp; {fmtTime(selection.start_ms,true)} – {fmtTime(selection.end_ms,true)} <span>({duration(selection.end_ms-selection.start_ms)})</span></div><dl>{selectedImu?.acc!==null&&selectedImu?.acc!==undefined&&<><dt>ACC magnitude (mean)</dt><dd>{selectedImu.acc.toFixed(2)} {activeMotion?.manifest.units.acceleration==='g'?'g':'counts'}</dd></>}{selectedImu?.gyro!==null&&selectedImu?.gyro!==undefined&&<><dt>Angular velocity (mean)</dt><dd>{selectedImu.gyro.toFixed(2)} {activeMotion?.manifest.units.gyroscope==='raw_adc'?'counts':activeMotion?.manifest.units.gyroscope}</dd></>}<dt>Candidate</dt><dd>{selectedCandidate?selectedCandidate.admitted?'Admitted':'Not admitted':'None'}</dd>{selectedCandidate&&<><dt>Candidate score</dt><dd>{selectedCandidate.score.toFixed(3)}</dd></>}<dt>Model decision</dt><dd><span className={selectedEvent?'decision eating':'decision'}>{selectedEvent?'Eating event':'No event overlaps'}</span></dd></dl></>:<div className="panel-empty">Drag on the timeline or click an event.</div>}</section>
          <RawChart imu={activeMotion?.imu} selection={selection} playhead={playhead} orientation={orientation}/>
          <section className="panel context"><h2>Event context</h2>{selectedEvent?<dl><dt>Start time</dt><dd className="mono">{fmtTime(selectedEvent.start_ms,true)}</dd><dt>End time</dt><dd className="mono">{fmtTime(selectedEvent.end_ms,true)}</dd><dt>Duration</dt><dd>{duration(selectedEvent.end_ms-selectedEvent.start_ms)}</dd><dt>Event score</dt><dd>{selectedEvent.confidence.toFixed(3)}</dd><dt>Session</dt><dd>{selectedEvent.session_id}</dd></dl>:<div className="panel-empty">Select an eating event to inspect its context.</div>}</section></div>
      </>}
      {page==='Events'&&<section className="panel events-page"><div className="page-title"><div><h1>Events</h1><p>Canonical model output · select a record to inspect it on Monitor.</p></div><span>{demo?'DEMO DATA':'REAL PREDICTION'}</span></div>{prediction.events.length?prediction.events.map(e=><button key={`${e.session_id}-${e.id}`} className="event-record" onClick={()=>{setSessionId(e.session_id);select(e);setPage('Monitor');}}><span className="record-date">{new Date(e.start_ms).toLocaleDateString('en-CA')}</span><strong className="mono">{fmtTime(e.start_ms,true)} – {fmtTime(e.end_ms,true)}</strong><span>{duration(e.end_ms-e.start_ms)}</span><span>Event score {e.confidence.toFixed(3)}</span><b>Inspect →</b></button>):<div className="panel-empty">No eating events in this prediction.</div>}</section>}
      {page==='Model'&&<section className="panel model-page"><div className="page-title"><div><h1>Model</h1><p>Promoted release metadata and inference contract.</p></div></div><div className="model-grid"><div><h2>Release evidence</h2><p>Subject-disjoint nested 5-fold cross-validation. Development evidence; not an independent test score.</p><dl><dt>Run key</dt><dd className="mono">{release?.run_key||prediction.model.run_key}</dd><dt>F1</dt><dd>{release?.outer_metrics?.f1?.toFixed(3)||release?.f1?.toFixed(3)||'—'}</dd><dt>Precision / PPV</dt><dd>{release?.outer_metrics?.ppv?.toFixed(3)||'—'}</dd><dt>Recall / sensitivity</dt><dd>{release?.outer_metrics?.sensitivity?.toFixed(3)||'—'}</dd><dt>TP / eligible / predictions</dt><dd>{release?.outer_metrics?`${release.outer_metrics.n_tp} / ${release.outer_metrics.n_true} / ${release.outer_metrics.n_pred}`:'—'}</dd></dl></div><div><h2>Inference path</h2><div className="pipeline">Raw wrist IMU <span>↓</span> Macro / Micro <span>↓</span> Candidate admission <span>↓</span> Context + event verifier <span>↓</span> Eating episodes</div><p className="muted">Visualization only consumes the published prediction contract and optional motion telemetry.</p></div></div></section>}
    </main></div>;
}


